import{_ as t,c as s,A as a,k as i}from"./index-DPgel6Xp.js";const r={},o={class:"max-w-3xl mx-auto space-y-8"};function l(n,e){return i(),s("div",o,[...e[0]||(e[0]=[a('<header><h1 class="text-3xl font-bold tracking-tight"> About Wiki<span class="text-blue-600 dark:text-blue-400">STAR</span></h1><p class="mt-3 text-neutral-600 dark:text-neutral-300"> WikiSTAR is a submission, review and self-assessment tool for Wikipedia and Wikidata editathons and writing contests, running on Wikimedia Toolforge. </p></header><section class="card p-5 space-y-3"><h2 class="text-lg font-semibold">What it does</h2><ul class="list-disc pl-5 space-y-2 text-sm text-neutral-700 dark:text-neutral-300"><li><strong>Organizers</strong> create campaigns: dates, target wiki, scoring mode, configurable point rules, jury members and suggested page lists. </li><li><strong>Participants</strong> log in with their Wikimedia account and submit articles or Wikidata items. Page metadata — bytes added, new-page detection — is verified against the MediaWiki API, never trusted from user input. </li><li><strong>Juries</strong> score submissions (jury mode), or verify participants&#39; point claims (self-assessment and hybrid modes). </li></ul></section><section class="card p-5 space-y-3"><h2 class="text-lg font-semibold">Scoring modes</h2><table class="w-full"><thead><tr class="border-b border-neutral-200 dark:border-neutral-800"><th class="th">Mode</th><th class="th">Who counts the points</th></tr></thead><tbody class="divide-y divide-neutral-100 dark:divide-neutral-800"><tr><td class="td font-mono">jury</td><td class="td">Jurors review every submission; points are the average of accepting reviews.</td></tr><tr><td class="td font-mono">self</td><td class="td">Participants claim points under the campaign&#39;s rules; organizers verify or adjust and always have the final say.</td></tr><tr><td class="td font-mono">hybrid</td><td class="td">Self-assessment claims combined with jury verification.</td></tr></tbody></table><p class="text-sm text-neutral-600 dark:text-neutral-400"> Point rules (per-1,000-bytes, substantial improvement, suggested pages, quality awards, Wikidata statements, …) are stored per campaign and fully editable; a default preset ships with the tool. </p></section><section class="card p-5 space-y-3"><h2 class="text-lg font-semibold">Privacy</h2><p class="text-sm text-neutral-700 dark:text-neutral-300"> Signing in uses MediaWiki OAuth 2.0: WikiSTAR never sees your password and stores only your Wikimedia username, the campaigns you take part in and the submissions, reviews and claims you make. </p></section><section class="card p-5 space-y-3"><h2 class="text-lg font-semibold">Links</h2><ul class="space-y-2 text-sm"><li><a class="text-blue-600 dark:text-blue-400 hover:underline" href="https://gitlab.wikimedia.org/toolforge-repos/wikistar" target="_blank" rel="noopener">Source code on Wikimedia GitLab</a></li><li><a class="text-blue-600 dark:text-blue-400 hover:underline" href="https://gitlab.wikimedia.org/toolforge-repos/wikistar/-/issues" target="_blank" rel="noopener">Bug reports and feature requests</a></li><li><a class="text-blue-600 dark:text-blue-400 hover:underline" href="https://toolforge.org" target="_blank" rel="noopener"> Wikimedia Toolforge</a>, which hosts this tool </li><li><a class="text-blue-600 dark:text-blue-400 hover:underline" href="https://meta.wikimedia.org/wiki/User:Ranjithsiji" target="_blank" rel="noopener">Ranjithsiji</a>, maintainer </li></ul></section><section class="card p-5 space-y-3"><h2 class="text-lg font-semibold">License</h2><p class="text-sm text-neutral-700 dark:text-neutral-300"> WikiSTAR is free software, released under the <a class="text-blue-600 dark:text-blue-400 hover:underline" href="https://www.gnu.org/licenses/gpl-3.0.html" target="_blank" rel="noopener">GNU General Public License v3.0</a> (or any later version), in line with Toolforge&#39;s <a class="text-blue-600 dark:text-blue-400 hover:underline" href="https://wikitech.wikimedia.org/wiki/Wikitech:Cloud_Services_Terms_of_use" target="_blank" rel="noopener">right-to-fork policy</a>. Scoring behaviour follows the model established by the <a class="text-blue-600 dark:text-blue-400 hover:underline" href="https://fountain.toolforge.org" target="_blank" rel="noopener">Fountain</a> tool. </p></section>',6)])])}const c=t(r,[["render",l]]);export{c as default};
